#include <stdint.h>


uint32_t color = 0;


int main(void)
{
	//setting up the SYSCLCK
	uint32_t* RCC_CR = (uint32_t*)(0x40021000);
	*RCC_CR |= (1U << 8); //setting the HSION flag to ON

	uint32_t* RCC_CFGR = (uint32_t*)(0x40021000 + 0x08);
	//check HSIRDY flag
	while (!(*RCC_CR & (1U << 10))) { }

	//HSI16 SELECTED, NEED 01 IN BIT PLACE 0,1
	*RCC_CFGR &= ~(3U << 0); //CLEAR
	*RCC_CFGR |= (1U << 0); //SET

	//HSI16 OSCILLATOR USED, ALSO NEED 01 IN BIT PLACE (2,3)
	while ((((*RCC_CFGR) >> 2) & 3U) != 1U) {}



	//configure GPIOB AHB2ENR for clocks and lED
	uint32_t RCC_AHB2ENR = 0x40021000;
	uint32_t RCC_AHB2ENR_OFFSET = 0x4C;

	uint32_t* AHB2ENR = (uint32_t*)(RCC_AHB2ENR + RCC_AHB2ENR_OFFSET);

	//want to ENABLE -- want to make bit 1, 1 or bit 2 if its the button
	*AHB2ENR |= (1U << 1) | (1U << 2);


	////BLUE LED - PB7 - 2
	uint32_t* GPIOB_MODER = (uint32_t*) 0x48000400;
	//bit 14 to 1 to make this an output
	*GPIOB_MODER |= (1U << 14);
	*GPIOB_MODER = *GPIOB_MODER & ~(1U << 15);

	//green LED - PC7 - 1
	uint32_t* GPIOC_MODER = (uint32_t*) 0x48000800;
	//bit 14 to 1 to make this an output
	*GPIOC_MODER |= (1U << 14); // write
	*GPIOC_MODER = *GPIOC_MODER & ~(1U << 15); // write

	//red LED - 3
	//bit 28 to 1 to make this an output
	*GPIOB_MODER |= (1U << 28); // write
	*GPIOB_MODER = *GPIOB_MODER & ~(1U << 29); // write



	//Turn on green first
	uint32_t* GPIO_CURR = (uint32_t*)(0x48000800 + 0x14);
	*GPIO_CURR |= (1U << 7); // make it go high
	color = 1;



	//enable tim4
	uint32_t* RCC_APB1ENR1 = (uint32_t*)(0x40021000 + 0x58);
	*RCC_APB1ENR1 |= (1U << 2); //set bit 2 to 1

	//prescalar tim4
	uint32_t* TIM4_PSC = (uint32_t*)(0x40000800 + 0x28);
	//set the value 15999
	*TIM4_PSC = 15999;

	uint32_t* TIM4_ARR = (uint32_t*)(0x40000800 + 0x2C);
	//set the value 999
	*TIM4_ARR = 999;

	uint32_t* TIM4_EGR = (uint32_t*)(0x40000800 + 0x14);
	*TIM4_EGR |= (1U << 0); //set bit 0 to 1


	//update interrupt
	uint32_t* TIM4_DIER = (uint32_t*)(0x40000800 + 0x0C);
	//update interrupt enabled
	*TIM4_DIER |= (1U << 0);

	//handle the NVIC for the clock and set the position bit
	uint32_t* NVIC_ISER0 = (uint32_t*)0xE000E100;
	*NVIC_ISER0 |= (1U << 30); //set bit 30 to 1

	//start counter
	uint32_t* TIM4_CR1 = (uint32_t*)(0x40000800);
	//counter enabled
	*TIM4_CR1 |= (1U << 0);


	// your code goes here
	while(1)
	{

	};
}


void TIM4_IRQHandler(void) {
	//Status register
	uint32_t* TIM4_SR = (uint32_t*)(0x40000800 + 0x10);
	uint32_t* GPIOB_CURR = (uint32_t*)(0x48000400 + 0x14);
	uint32_t* GPIOC_CURR = (uint32_t*)(0x48000800 + 0x14);

	if ((*TIM4_SR & (1U << 0))) {
		//set bit 0 to 0, otherwise its changed by the hardware
		*TIM4_SR &= ~(1U << 0);

		//turn them off
		*GPIOB_CURR &= ~(1U << 14);
		*GPIOB_CURR &= ~(1U << 7);
		*GPIOC_CURR &= ~(1U << 7);

		//cycle through the colors-move through them
		color = (color + 1) % 3;

		if (color == 1) {
			*GPIOC_CURR |= (1U << 7); //turn on green

		} else if (color == 2) {
			*GPIOB_CURR |= (1U << 7); //turn on blue
		} else {
			*GPIOB_CURR |= (1U << 14); //turn on red
		}


	}




}








